export const NAKSHATRA_LECTURES_RU = {
  "Ашвини": "1. Ашвини.\nСозвездия (IAU, J2000): Рыбы → Овен. Управитель: Кету.\nСимвол: голова Лошади.\nБожество: Кумары (братья-близнецы).\nКлючевое слово: Импульсивность.\nСильные стороны: быстрота, старт, инициатива, «сделать невозможное», целительная энергия.\nТеневая сторона: нетерпение, трудность подчинения, «промедление — смерти подобно».\nГармонизация (если Луна в Ашвини): контакт с Лошадьми (хобби/конный спорт), места конюшен/пастбищ; тема медицины/исцеления.\nПрофессии/роли: запуск проектов/стартапов, экспедиции, медицина/госпитали, задачи «с нуля в тяжёлых условиях».\nМухурта:\n✅ Благоприятно: начало лечения, улучшение внешности/уход за волосами, починка транспорта, начало путешествия.\n⛔ Неблагоприятно: свадьбы (много огня), завершение дел.\nПримечания: если Кету в Овне в Ашвини — подчёркнуты таланты прошлого (целительство/ясновидение).",
  "Бхарани": "2. Бхарани.\nСозвездия (IAU, J2000): Овен. Управитель: Венера.\nСимвол: Йони (женский детородный орган).\nБожество: Ямарадж (Бог смерти).\nКлючевое слово: Крайности.\nСильные стороны: страсть, привлекательность, энергия рождения, первопроходцы, выдержка в трудностях, творческие идеи.\nТеневая сторона: крайности, перегибы, риск конфликтов/аварийности.\nГармонизация (если Луна в Бхарани): экологичная дисциплина желаний, контроль крайностей.\nПрофессии/роли: массаж, дизайн, танцы, актёрство, гинекология, темы «жизнь–смерть».\nМухурта:\n✅ Благоприятно: зачатие детей.\n⛔ Неблагоприятно: большинство начинаний, свадьбы (Ямарадж), повышенные риски (пробки/ДТП).\nПримечания: сочетание Марса (Овен) и Венеры (упр. накшатры) даёт сильную страсть.",
  "Криттика": "3. Криттика.\nСозвездия (IAU, J2000): Овен → Телец. Управитель: Солнце.\nСимвол: режущий инструмент.\nБожество: Агни (Бог огня).\nКлючевое слово: Очищение.\nСильные стороны: лидерство, ответственность, очищающий огонь, решительность.\nТеневая сторона: излишняя резкость/«пережигание», конфликтность.\nГармонизация (если Луна в Криттике): огонь в благости — костёр/камин, «очищающие практики».\nПрофессии/роли: часть в Овне — военные/командиры; часть в Тельце — мода/шоу-бизнес.\nМухурта:\n✅ Благоприятно: отказ от вредных привычек, диета, «сжечь старое».\n⛔ Неблагоприятно: большинство «мирских» начинаний и свадьбы.\nМеста — полигоны, горячие цеха, у камина, у костра.",
  "Рохини": "4. Рохини.\nСозвездия (IAU, J2000): Телец. Управитель: Луна.\nСимвол: колесница.\nБожество: Брахма.\nКлючевое слово: Постоянство.\nСильные стороны: плодородие, материализация желаний, стабильность, «любимая накшатра Луны».\nТеневая сторона: привязанность к комфорту/материализации (если уход в крайности).\nГармонизация (если Луна в Рохини): посев/сад/созидательные занятия, доска визуализации.\nПрофессии/роли: всё, что связано с созиданием и ростом.\nМухурта:\n✅ Благоприятно: почти любые начинания, свадьбы, посев/урожай, создание «доски желаний».\n⛔ Неблагоприятно: явных нет.\nПримечания: идеальна для любых начинаний, романов, предложений.",
  "Мригашира": "5. Мригашира.\nСозвездия (IAU, J2000): Телец. Управитель: Марс.\nСимвол: голова Оленя.\nБожество: энергия Шакти.\nКлючевое слово: Любопытство.\nСильные стороны: мягкость, артистизм, поиск знаний, интеллект, неконфликтность.\nТеневая сторона: распыление, трудность фокуса.\nГармонизация (если Луна в Мригашире): обучение, путешествия «за знаниями».\nПрофессии/роли: артист, музыкант, путешественник, поэт, дизайн.\nМухурта:\n✅ Благоприятно: свадьбы, церемонии, зачатие детей, смена имени.\nПримечания: люди, у которых Луна в накшатре Мригашира обладают большими, красивыми глазами «оленьи глаза»",
  "Ардра": "6. Ардра.\nСозвездия (IAU, J2000): Телец → Близнецы. Управитель: Раху.\nСимвол: слеза, бриллиант.\nБожество: Рудра.\nКлючевое слово: Буря.\nСильные стороны: интеллект, способность «видеть ясно после слёз», сильная умственная энергия.\nТеневая сторона: бури, боль себе/другим, тяжёлые жизненные сценарии, риск «интеллект во зло».\nГармонизация (если Луна в Ардре): направлять Раху в благость (интеллект на созидание).\nПрофессии/роли: электричество, химия, яды (осторожно), медицина/врачи.\nМухурта:\n✅ Благоприятно: интеллектуальная работа, исследования.\n⛔ Неблагоприятно: всё, где опасны «бури» и токсичность (по смыслу накшатры).",
  "Пунарвасу": "7. Пунарвасу.\nСозвездия (IAU, J2000): Близнецы. Управитель: Юпитер.\nСимвол: лук.\nБожество: Адити.\nКлючевое слово: «Вновь хорошая» (перезапуск).\nСильные стороны: начинать сначала, обучение (астрология/психология), вскармливание/поддержка.\nТеневая сторона: не лучший фон для выяснения отношений.\nГармонизация (если Луна в Пунарвасу): темы заботы, питания, восстановления.\nПрофессии/роли: обучение, консультирование, поддерживающие профессии.\nМухурта:\n✅ Благоприятно: почти любая деятельность, особенно «начать заново».\n⛔ Неблагоприятно: выяснение отношений.",
  "Пушья": "8. Пушья.\nСозвездия (IAU, J2000): Близнецы → Рак. Управитель: Сатурн.\n Одна из лучших накшатр.\nКлючевое слово: Благословение.\nСильные стороны: №1 для начинаний, нейтрализует трудности, служение, забота о семье/мире.\nТеневая сторона: для свадьбы «не идеально» из-за Сатурна.\nГармонизация (если Луна в Пушье): служение, семейные дела, благочестивые практики.\nПрофессии/роли: писатели/ораторы (Меркурий в Пушье), служение; Если Марс в Пушье, в падении — это как нейтрализация агрессии.\nМухурта:\n✅ Благоприятно: почти любые дела/практики (считается, что трудности уходят).\n⛔ Неблагоприятно: свадьбы — спорно/осторожно.\nПримечания: в лекции — если есть Луна+Сатурн+Юпитер (соединение/аспекты), это «как Пушья».",
  "Ашлеша": "9. Ашлеша.\nСозвездия (IAU, J2000): Рак → Лев. Управитель: Меркурий.\nСимвол: свернувшаяся змея.\nБожество: Наги (змеи).\nКлючевое слово: Проницательность.\nСильные стороны: эмоциональная устойчивость, хладнокровие, мудрость, интуиция (Меркурий+Луна).\nТеневая сторона: подозрительность, «трудная энергия в обращении», жёсткость при слабом Марсе.\nГармонизация (если Луна в Ашлеше): перевод ума в благость, йога/контроль речи и намерений.\nПрофессии/роли: связанные с нефтью, шпионаж, йоги, гипноз, психология/астрология.\nМухурта:\n⛔ Неблагоприятно: всё, где есть интриги/ядовитость.\nПримечания: в конце — важно усиливать благие качества накшатры.",
  "Магха": "10. Магха.\nСозвездия (IAU, J2000): Лев. Управитель: Кету.\nЭто всегда царский , крепкий , благочестивый род.\nКлючевое слово: Род.\nСильные стороны: царственность, благородство, поддержка рода, накопленная карма.\nТеневая сторона: при периоде Кету — ощущение «нет ничего», отстранённость.\nГармонизация (если Луна в Магхе): связь с предками, служение роду.\nПрофессии/роли: руководитель, публичные роли.\nМухурта:\n✅ Благоприятно: коронации, награждения, выступления, публичность.\nПримечания: Если у вас есть соединение Кету с Солнцем в карте, либо есть аспект (например Солнце есть на Ке), то это как маг, связь с родом, предками.",
  "Пурвапхалгуни": "11. Пурвапхалгуни.\nСозвездия (IAU, J2000): Лев. Управитель: Венера.\nСимвол: ложе, гамак.\nКлючевое слово: Наслаждение.\nСильные стороны: красота, заметность, комфорт, дипломатичность, творчество.\nТеневая сторона: свирепость, сложности с субординацией. Болезни, которые начинаются в эту Накшатру, очень сложны для лечения.\nГармонизация (если Луна в Пурвапхалгуни): дисциплина наслаждений, эстетика в благости.\nПрофессии/роли: госслужба, дипломатия, ювелирка, благовония.\nМухурта:\n⛔ Неблагоприятно: начинания не благоприятны, осторожно со здоровьем.\nПримечания: «если в люди выходить» — должен быть важный мотив.",
  "Уттарапхалгуни": "12. Уттарапхалгуни.\nСозвездия (IAU, J2000): Лев → Дева. Управитель: Солнце\nСимвол: кровать.\nБожество: Арьяман.\nКлючевое слово: Помощь.\nСильные стороны: духовный рост, воспитанность, независимость; успех через брак (созвездие Льва), интеллект (созвездие Девы).\nТеневая сторона: ключевой риск — не завершать дела.\nГармонизация (если Луна в Уттарапхалгуни): служение людям, правильные союзы.\nПрофессии/роли: интеллект/аналитика, управление, помощь.\nМухурта:\n✅ Благоприятно: любые начинания, стрижки (если управитель Венера), системные планы.\n⛔ Неблагоприятно: завершение деятельности (если управитель Солнце).\nПримечания: Уттарапхалгуни в целом благоприятнее чем Пурвапхалгуни.",
  "Хаста": "13. Хаста.\nСозвездия (IAU, J2000): Дева. Управитель: Луна.\nСимвол: ладонь, кулак.\nБожество: Савитар.\nКлючевое слово: Мастерство.\nСильные стороны: талант рук (ремёсла), изобретательность, точность, пунктуальность, оптимизм.\nТеневая сторона: внутренний гнев (если Марс в Деве/Хасте), перфекционизм.\nГармонизация (если Луна в Хасте): делать руками, ремесло, музыка, служение делу.\nПрофессии/роли: ремесленник, ювелир, хиромант, изобретатель, торговля.\nМухурта:\n✅ Благоприятно: долгие системные проекты, покупки/продажи, ремесло.\nПримечания: Венера в Деве в падении, но Хаста может давать «нейтрализацию» через дизайн.",
  "Читра": "14. Читра.\nСозвездия (IAU, J2000): Дева. Управитель: Марс.\nСимвол: жемчужина.\nБожество: Вишвакарма.\nКлючевое слово: Созидание.\nСильные стороны: архитектура/дизайн, масштабное мышление, способность «строить города», яркость.\nТеневая сторона: творить «не заботясь о последствиях», желание затмить других.\nГармонизация (если Луна в Читре): созидательные проекты + жизнь по законам Вселенной.\nПрофессии/роли: архитектура, васту, дизайн, продажи/сети, инженерия.\nМухурта:\n✅ Благоприятно: созидание, свадьбы.",
  "Свати": "15. Свати.\nСозвездия (IAU, J2000): Дева → Весы. Управитель: Раху.\nСимвол: коралл, росток, меч.\nБожество: Ваю.\nКлючевое слово: Свобода.\nСильные стороны: коммуникации, скорость, дипломатия, продажи, ораторство, бизнес.\nТеневая сторона: неугомонность, беспокойство, склонность к плохим привычкам при Раху в невежестве.\nГармонизация (если Луна в Свати): дисциплина ветра/ума, режим, чистые коммуникации.\nПрофессии/роли: переговорщик, продавец, дипломат, политика, СМИ.\nМухурта:\n✅ Благоприятно: переговоры, бизнес, выступления, покупки/продажи; свадьбы — хорошо если тема заграницы (поскольку Раху управитель).\n⛔ Неблагоприятно: хаотичные удовольствия, зависимости.\nПримечания: «могут уговорить кого угодно» — ключевой дар Свати.",
  "Вишакха": "16. Вишакха.\nСозвездия (IAU, J2000): Весы. Управитель: Юпитер.\nСимвол: арка / гончарный круг.\nБожество: Индра и Агни.\nКлючевое слово: Цель.\nСильные стороны: всегда достигают цели, ставят новые цели, сила реализации.\nТеневая сторона: «идея фикс», навязчивые цели, бурные празднования после успеха.\nГармонизация (если Луна в Вишакхе): усиливать Юпитер (чтобы цели были в благости).\nПрофессии/роли: политики, агитаторы, солдаты, революционеры, астрологи, охрана/таможня, бармен.\nМухурта:\n✅ Благоприятно: медитации, встречи с друзьями, раскаяние, решения, постановка целей.\n⛔ Неблагоприятно: начинания — «условно можно», но осторожно.",
  "Анурадха": "17. Анурадха.\nСозвездия (IAU, J2000): Весы → Скорпион. Управитель: Сатурн.\nСимвол: лотос, посох.\nБожество: Митра (ещё «Ратха» как мотив пути).\nКлючевое слово: Дружба.\nСильные стороны: мягкость, гармония со Вселенной, трудолюбие, оптимизм, умение объединять людей.\nТеневая сторона: если уходить в «мирское» без пути — внутреннее беспокойство.\nГармонизация (если Луна в Анурадхе): дружба, служение, дисциплина Сатурна + путь к Богу.\nПрофессии/роли: руководитель, промоутер, дипломат, учёный, математик, психолог.\nМухурта:\n✅ Благоприятно: медитации, встречи с друзьями, спокойные размышления.\n⛔ Неблагоприятно: ссоры, раздоры.\nПримечания: «мягкий Скорпион» — маркер Анурадхи (по лекции).",
  "Джйештха": "18. Джйештха.\nСозвездия (IAU, J2000): Скорпион. Управитель: Меркурий.\nСимвол: Вожак, экипаж, главный).\nКлючевое слово: Старшинство.\nСильные стороны: защита слабых, справедливость, аналитика, лидерство.\nТеневая сторона: ревность, властность, навязчивое «спасательство».\nГармонизация (если Луна в Джйештхе): служение без контроля, уважение к старшим.\nПрофессии/роли: полиция/защитники, руководители, бюрократы, покровители.\nМухурта:\n✅ Благоприятно: помощь пожилым, забота о животных.\n⛔ Неблагоприятно: свадьбы, покупки/продажи.\nПримечания: 2 планеты в Джйештхе — это нормально, 3 — уже неблагоприятно.",
  "Мула": "19. Мула.\nСозвездия (IAU, J2000): Скорпион → Стрелец. Управитель: Кету.\nСимвол: связка корней, погоняло для слонов.\nБожество: Ниррити.\nКлючевое слово: Корень.\nСильные стороны: докопаться до сути, глубинный смысл, тяга к духовности, т.к. Кету (управитель накшатры) + Юпитер (управитель Стрельца).\nТеневая сторона: «сначала даёт — потом забирает», потери, может «делать больно».\nГармонизация (если Луна в Муле): укреплять Юпитер/смысл, духовные практики, изучение писаний.\nПрофессии/роли: исследователь, оратор, учёный, философ.\nМухурта:\n✅ Благоприятно: духовные практики, изучение, работа с причиной.\n⛔ Неблагоприятно: мирские начинания.\nПримечания: Кету в Муле — «как Кету в своём знаке», сильная проработка прошлого.",
  "Пурваашадха": "20. Пурваашадха.\nСозвездия (IAU, J2000): Стрелец. Управитель: Венера.\nСимвол: слоновый бивень.\nБожество: Варуна.\nКлючевое слово: Победа.\nСильные стороны: уверенность, умение переждать трудное, целеустремлённость.\nТеневая сторона: суровый нрав, лень «как двигатель», риск свирепости.\nГармонизация (если Луна в Пурваашадхе): дисциплина удовольствий, цель в благости.\nПрофессии/роли: суды, борьба за правоту, смелые задачи.\nМухурта:\n✅ Благоприятно: отстаивать позицию, суды, конкуренция, смелые решения.\n⛔ Неблагоприятно: начинания в целом (Пурвы).\nПримечания: Кету — уверенность из прошлого; Раху — задача развить уверенность.",
  "Уттараашадха": "21. Уттараашадха.\nСозвездия (IAU, J2000): Стрелец → Козерог. Управитель: Солнце.\nСимвол: маленькая хижина.\nБожество: 10 Вишвадэвов.\nКлючевое слово: Обязательства.\nСильные стороны: царские качества, ответственность, доводит до конца, создаёт союзы/альянсы.\nГармонизация (если Луна в Уттараашадхе): планирование, служение, держать слово.\nПрофессии/роли: управленцы, организаторы, лидеры.\nМухурта:\n✅ Благоприятно: любые дела, списки задач, системные начинания.\nПримечания: одна из лучших накшатр для деятельности.",
  "Шравана": "22. Шравана.\nСозвездия (IAU, J2000): Козерог. Управитель: Луна.\nСимвол: ухо.\nБожество: Вишну.\nКлючевое слово: Слышание.\nСильные стороны: слышать «голос Творца», знания, точная речь, социальная активность, удача (как нейтрализация плохого).\nГармонизация (если Луна в Шраване): медитации через слушание, музыка/знания, общественная польза.\nПрофессии/роли: преподавание, речь, знания, музыка.\nМухурта:\n✅ Благоприятно: все начинания.\nПримечания: сильна как Пушья.",
  "Дхаништха": "23. Дхаништха.\nСозвездия (IAU, J2000): Козерог. Управитель: Марс.\nСимвол: барабан и флейта.\nБожество: 8 Васу.\nКлючевое слово: Ритм.\nСильные стороны: дерзость, решительность, надёжность, музыка/праздники, способность гармонизировать Марс и Сатурн.\nТеневая сторона: материальная жадность/жёсткость при перекосе.\nГармонизация (если Луна в Дхаништхе): музыка, дарение, служение людям.\nПрофессии/роли: организатор мероприятий, музыка, управление, служение.\nМухурта:\n✅ Благоприятно: крупные праздники, концерты, церемонии.\n⛔ Неблагоприятно: отказываться от старых привычек.",
  "Сатабхиша": "24. Сатабхиша.\nСозвездия (IAU, J2000): Козерог → Водолей. Управитель: Раху.\nСимвол: «100 врачей».\nБожество: Варуна.\nКлючевое слово: Исцеление.\nСильные стороны: медицина/целительство, психология, астрология, СМИ/электроника, поиск истины.\nТеневая сторона: трудные болезни, аскетизм, потери (семьи/денег) как сценарии Раху.\nГармонизация (если Луна в Сатабхише): чистота Раху, духовная дисциплина.\nПрофессии/роли: врач, целитель, психолог, астролог, тех/медиа.\nМухурта:\n✅ Благоприятно: исследования, лечение (в целом).\n⛔ Неблагоприятно: начинания — «стоит задуматься», болезни могут быть трудноизлечимыми; лечить лучше стартовать в Ашвини (конечно если есть время).\nПримечания: Мула и Сатабхиша — аскетичные накшатры.",
  "Пурвабхадрапада": "25. Пурвабхадрапада.\nСозвездия (IAU, J2000): Водолей → Рыбы. Управитель: Юпитер.\nСимвол: двуликий человек, меч.\nБожество: Аджайкапада.\nКлючевое слово: Риск.\nСильные стороны: (в тексте акцент на «ночную жизнь/двойственность», сила выживания).\nТеневая сторона: насилие, ложь, пороки, эго-искажения.\nГармонизация (если Луна в Пурвабхадрападе): улучшать Юпитер, выводить жизнь в благость.\nПрофессии/роли: риск-профессии, кризисы, темы траура.\nМухурта:\n✅ Благоприятно: риск, траур, похороны.\n⛔ Неблагоприятно: обычные мирские начинания.\nПримечания: накшатра неблагоприятная.",
  "Уттарабхадрапада": "26. Уттарабхадрапада.\nСозвездия (IAU, J2000): Рыбы. Управитель: Сатурн.\nСимвол: две ножки кровати/стула.\nБожество: Лакшми.\nКлючевое слово: Мудрость.\nСильные стороны: сострадание, рост, выгода, консультационный дар, стабильность.\nГармонизация (если Луна в Уттарабхадрападе): дисциплина Сатурна + благость, помощь людям.\nПрофессии/роли: консультант, наставник; «профессии Юпитера и Сатурна».\nМухурта:\n✅ Благоприятно: все начинания.",
  "Ревати": "27. Ревати.\nСозвездия (IAU, J2000): Рыбы.\nСимвол: Рыба. Управитель: Меркурий.\nБожество: Пушан.\nКлючевое слово: Завершение.\nСильные стороны: мягкость, путешествия, сделки, любовь людей, интуиция, «выходить за пределы».\nТеневая сторона: истощение из-за проблем других, трудность говорить «нет».\nГармонизация (если Луна в Ревати): границы, отдых, учиться говорить «нет».\nПрофессии/роли: торговля/сделки, путешествия, коммуникации (по смыслу Меркурия).\nМухурта:\n✅ Благоприятно: завершать дела, покупки (например, авто), свадьбы, сделки.\n⛔ Неблагоприятно: перегрузка заботами других.\nПримечания: последовательность ведущей накшатры: Луна → Солнце → Асцендент."
} as const;

